import app from 'flarum/common/app';

/** What a chapter's discussion page carries (the `anthologySeries` attribute). */

const api = path => app.forum.attribute('apiUrl') + '/anthology' + path;
export const listSeries = params => app.request({
  method: 'GET',
  url: api('/series'),
  params
});
export const showSeries = id => app.request({
  method: 'GET',
  url: api('/series/' + id)
});
export const saveSeries = (id, data) => app.request({
  method: id ? 'PATCH' : 'POST',
  url: api('/series' + (id ? '/' + id : '')),
  body: {
    data
  }
});
export const deleteSeries = id => app.request({
  method: 'DELETE',
  url: api('/series/' + id)
});
export const uploadCover = (id, file) => {
  const body = new FormData();
  body.append('cover', file);
  return app.request({
    method: 'POST',
    url: api('/series/' + id + '/cover'),
    serialize: raw => raw,
    body
  });
};
export const removeCover = id => app.request({
  method: 'DELETE',
  url: api('/series/' + id + '/cover')
});
export const follow = (id, on) => app.request({
  method: on ? 'POST' : 'DELETE',
  url: api('/series/' + id + '/follow')
});
export const reorder = (id, ids) => app.request({
  method: 'PATCH',
  url: api('/series/' + id + '/order'),
  body: {
    data: {
      ids
    }
  }
});
export const addChapter = (discussionId, seriesId) => app.request({
  method: 'POST',
  url: api('/chapters'),
  body: {
    data: {
      discussionId,
      seriesId
    }
  }
});
export const removeChapter = discussionId => app.request({
  method: 'DELETE',
  url: api('/chapters/' + discussionId)
});
flarum.reg.add('ernestdefoe-anthology', 'common/api', { listSeries: listSeries,showSeries: showSeries,saveSeries: saveSeries,deleteSeries: deleteSeries,uploadCover: uploadCover,removeCover: removeCover,follow: follow,reorder: reorder,addChapter: addChapter,removeChapter: removeChapter, });